vo1:"Допиши за {Y}: «Что меня выводит из себя, так это…» || Представь, как скажет {Y}: «Честно, меня раздражает…»",
vo2:"Допиши за {Y}: «Заведи меня на эту тему — и я не остановлюсь: …» || Что сказал(а) бы {Y}? «Моя любимая тема, о которой я могу говорить часами: …»",
