vo5:"Поставь себя на место {Y}: «Несправедливость, от которой я закипаю: …» || Закончи фразу. {Y}: «По-настоящему меня возмущает…»",
vo6:"Допиши за {Y}: «Меня не остановить, когда речь заходит о…» || Что сказал(а) бы {Y}? «Тема, о которой я могу говорить бесконечно: …»",
vo7:"Поставь себя на место {Y}: «Мне немного стыдно, но я обожаю…» || Закончи фразу. {Y}: «Моё маленькое тайное удовольствие: …»",
mo1:"«Я прикрою близкого, а не скажу всю правду.» || «Верность важнее честности.»",
mo2:"«Я легко отпускаю обиды.» || «Я не держу зла.»",
mo3:"«Я говорю как есть, даже если это злит.» || «Я честно высказываю мнение, даже если оно мешает.»",
mo4:"«Правило нужно соблюдать.» || «Я следую правилам, даже когда никто не видит.»",
mo5:"«Я выбираю надёжность, а не неизвестность.» || «Стабильность подходит мне больше, чем неожиданности.»",
mo6:"«Извиниться, даже когда прав, иногда необходимо.» || «Иногда я извиняюсь, только чтобы всё успокоилось.»",
mo7:"«Деньги влияют на мои решения.» || «Прежде чем выбрать, я думаю, сколько это будет стоить.»",
mo8:"«Доверенный мне секрет никогда не выйдет наружу.» || «Я храню чужие секреты, что бы ни случилось.»",
