gr5:"Что люди в тебе понимают неправильно. || Что бы ты хотел(а), чтобы другие лучше в тебе понимали.",
gr6:"Что ты скрываешь, когда тебе плохо. || Когда тебе плохо, что ты стараешься не показывать?",
